/**
 * Arabic interface copy — the language the dashboard ships in.
 *
 * One of two dictionaries split out of i18n.js on 2026-09-27: a visit only ever needs the
 * language it is shown in (switching language reloads the page, I18N.setLang), so loading
 * both cost every visit ~40KB gzipped for the language it would not show. The inline script
 * in index.html fetches this file during head parsing; `I18N.ready()` waits for it before the
 * app boots.
 *
 * Arabic must be complete: `check:i18n` fails on an English key with no Arabic twin, so an
 * Arabic page never needs the English file to fill a gap. Registration is order-independent
 * (this may run before or after i18n.js), which is why it writes into a shared object rather
 * than into `I18N`.
 *
 * Add a key here AND in i18n.en.js, in the same group, Arabic first.
 */
