    'ai.fallbackTitle': 'الرجوع إلى Gemini',
    'ai.fallbackDesc': 'إن فشل مزوّدو الذكاء الاصطناعي (لا مفتاح، أو انقطاع، أو انتهاء المهلة، أو نفاد الميزانية) أجاب Gemini مرة واحدة. وعند الإيقاف، أو إن فشل Gemini أيضاً، يتلقى الشخص سطراً واحداً يخبره بأن رسالته عند شخص يتابعها، وتظهر المحادثة «بانتظارك» في الرسائل، ويبقى المساعد مفعّلاً لرسالته التالية.',
