    'ai.salesTest': 'تجريبية (المرسلون أدناه فقط)',
    'ai.salesOn': 'مفعّلة (للجميع)',
    'ai.salesDesc': 'عند الإيقاف تبقى كل الردود كما هي اليوم تماماً. والوضع التجريبي يجعل مساعد المبيعات يردّ على مرسلي الاختبار المدرجين أدناه فقط، ويبقى الجميع على الردود المعتادة. أما التفعيل فيجعله يردّ على الجميع. ويكتب مساعد المبيعات عبر مسار «الردّ على الرسائل الخاصة» في التشغيل ← مزوّدو الذكاء الاصطناعي، أيّاً كان محرّك الردّ المختار أعلاه.',
