    'ai.salesFollowupDesc': 'تصل رسالة متابعة واحدة قصيرة وبلا إلحاح بعد هذه المدة من إرسال المساعد للرابط، بشرط ألّا يكون الشخص قد ردّ أو فتح الرابط أو طلب التوقف، وألّا يكون أحد قد تولّى المحادثة، وأن تكون نافذة ميتا البالغة 24 ساعة ما زالت مفتوحة. القيمة 240 تعني أربع ساعات، والقيمة 0 توقف المتابعة. وهذا إعداد واحد لكل الحسابات على هذا النشر.',
