    'ai.variants': 'تجربة الصياغة (A/B)',
    'ai.variantsDesc': 'اكتب طريقتين أو ثلاثًا لافتتاح المحادثة ولعرض الرابط. تحصل كل محادثة جديدة على واحدة منها بشكل دائم، تُختار بالصدفة وفق النسب التي تحددها، ويقارن قمع المبيعات في صندوق الوارد بين نتائجها. التجربة على الصياغة فقط: بلا روابط ولا أرقام، ويبقى المساعد لا يقول إلا ما تقوله عروضك. اترك خانتي أي صيغة فارغتين لتبقى ردودها كما هي اليوم. لا يشارك إلا المحادثات التي يجيب عنها مساعد المبيعات.',
